372	def validate_survey(obj):
373	    """Validate a decoded survey payload.
374	
375	    Returns (clean_survey, None) on success or (None, error_message) on failure.
376	    Strings are stored trimmed of surrounding whitespace; description keeps its
377	    raw value so Chinese, quotes and newlines are preserved.
378	    """
379	    if not isinstance(obj, dict):
380	        return None, "请求体必须是 JSON 对象"
381	    if "title" not in obj:
382	        return None, "缺少字段 title"
383	    title = obj["title"]
384	    if not isinstance(title, str):
385	        return None, "title 必须是字符串"
386	    title = title.strip()
387	    if not title:
388	        return None, "title 不能为空（或全为空白字符）"
389	
390	    description = obj.get("description", "")
391	    if not isinstance(description, str):
392	        return None, "description 必须是字符串"
393	
394	    if "questions" not in obj:
395	        return None, "缺少字段 questions"
396	    raw_questions = obj["questions"]
397	    if not isinstance(raw_questions, list):
398	        return None, "questions 必须是数组"
399	    if len(raw_questions) == 0:
400	        return None, "questions 至少需要一道题"
401	
402	    questions = []
403	    for index, raw_question in enumerate(raw_questions, start=1):
404	        location = f"第 {index} 题"
405	        if not isinstance(raw_question, dict):
406	            return None, f"{location}（questions[{index - 1}]）必须是对象"
407	
408	        if "type" not in raw_question:
409	            return None, f"{location}：缺少字段 type"
410	        question_type = raw_question["type"]
411	        if not isinstance(question_type, str):
412	            return None, f"{location}：type 必须是字符串"
413	        if question_type not in QUESTION_TYPES:
414	            shown = json.dumps(question_type, ensure_ascii=False)
415	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
416	
417	        if "title" not in raw_question:
418	            return None, f"{location}：缺少字段 title"
419	        question_title = raw_question["title"]
420	        if not isinstance(question_title, str):
421	            return None, f"{location}：title 必须是字符串"
422	        question_title = question_title.strip()
423	        if not question_title:
424	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
425	
426	        required = raw_question.get("required", False)
427	        if not isinstance(required, bool):
428	            return None, f"{location}：required 必须是布尔值"
429	
430	        raw_options = raw_question.get("options", [])
431	        if not isinstance(raw_options, list):
432	            return None, f"{location}：options 必须是数组"
433	
434	        options = []
435	        if question_type == "text":
436	            if len(raw_options) > 0:
437	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
438	        else:
439	            if len(raw_options) < 2:
440	                return None, f"{location}：单选题至少需要两个选项"
441	            seen = set()
442	            for option_index, raw_option in enumerate(raw_options, start=1):
443	                if not isinstance(raw_option, str):
444	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
445	                option = raw_option.strip()
446	                if not option:
447	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
448	                if option in seen:
449	                    shown = json.dumps(option, ensure_ascii=False)
450	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
451	                seen.add(option)
452	                options.append(option)
453	
454	        questions.append({
455	            "type": question_type,
456	            "title": question_title,
457	            "required": required,
458	            "options": options,
459	        })
460	
461	    return {
462	        "title": title,
463	        "description": description,
464	        "questions": questions,
465	    }, None
