468	def main():
469	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
470	    commands = parser.add_subparsers(dest="command", required=True)
471	    serve = commands.add_parser("serve", help="Start the HTTP service")
472	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
473	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
474	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
475	    args = parser.parse_args()
476	    if not 0 <= args.port <= 65535:
477	        parser.error("port must be between 0 and 65535")
478	    args.data_dir.mkdir(parents=True, exist_ok=True)
479	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite")
480	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
481	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
482	    if "description" not in columns:
483	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
484	    database.execute(
485	        "CREATE TABLE IF NOT EXISTS questions ("
486	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
487	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
488	    )
489	    database.execute(
490	        "CREATE TABLE IF NOT EXISTS question_options ("
491	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
492	    )
493	    database.commit()
494	
495	    def survey_detail(survey_id):
496	        row = database.execute(
497	            "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
498	            (survey_id,),
499	        ).fetchone()
500	        if row is None:
501	            return None
502	        title, description = row
503	        questions = []
504	        question_rows = database.execute(
505	            "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
506	            (survey_id,),
507	        ).fetchall()
508	        for question_id, question_type, question_title, required in question_rows:
509	            options = [option_row[0] for option_row in database.execute(
510	                "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
511	                (question_id,),
512	            )]
513	            questions.append({
514	                "type": question_type,
515	                "title": question_title,
516	                "required": bool(required),
517	                "options": options,
518	            })
519	        return {
520	            "id": survey_id,
521	            "title": title,
522	            "description": description,
523	            "questions": questions,
524	        }
525	
526	    def save_survey(clean):
527	        """Insert the whole survey atomically; returns the new id."""
528	        try:
529	            cursor = database.execute(
530	                "INSERT INTO surveys (title, description) VALUES (?, ?)",
531	                (clean["title"], clean["description"]),
532	            )
533	            survey_id = cursor.lastrowid
534	            for position, question in enumerate(clean["questions"]):
535	                question_cursor = database.execute(
536	                    "INSERT INTO questions (survey_id, position, type, title, required) "
537	                    "VALUES (?, ?, ?, ?, ?)",
538	                    (survey_id, position, question["type"], question["title"],
539	                     1 if question["required"] else 0),
540	                )
541	                question_id = question_cursor.lastrowid
542	                for option_position, option in enumerate(question["options"]):
543	                    database.execute(
544	                        "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
545	                        (question_id, option_position, option),
546	                    )
547	            database.commit()
548	            return survey_id
549	        except Exception:
550	            database.rollback()
551	            raise
552	
553	    class Handler(BaseHTTPRequestHandler):
554	        def respond(self, status, value, *, html=False, allow=None):
555	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
556	            self.send_response(status)
557	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
558	            self.send_header("Content-Length", str(len(payload)))
559	            if status == 405 and allow is not None:
560	                self.send_header("Allow", ", ".join(allow))
561	            self.end_headers()
562	            self.wfile.write(payload)
563	
564	        def list_surveys(self):
565	            records = [
566	                {"id": row[0], "title": row[1]}
567	                for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
568	            ]
569	            self.respond(200, {RESOURCE: records})
570	
571	        def create_survey(self):
572	            try:
573	                length = int(self.headers.get("Content-Length") or 0)
574	            except ValueError:
575	                length = -1
576	            if length < 0:
577	                self.respond(400, {"error": "Content-Length 无效"})
578	                return
579	            if length > MAX_BODY_BYTES:
580	                self.respond(400, {"error": "请求体过大"})
581	                return
582	            body = self.rfile.read(length) if length else b""
583	            try:
584	                payload = json.loads(body.decode("utf8"))
585	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
586	                self.respond(400, {"error": f"请求体不是合法 JSON：{error}"})
587	                return
588	
589	            clean, error = validate_survey(payload)
590	            if error is not None:
591	                self.respond(400, {"error": error})
592	                return
593	            try:
594	                survey_id = save_survey(clean)
595	            except sqlite3.DatabaseError as error:
596	                self.respond(500, {"error": f"保存失败：{error}"})
597	                return
598	            result = {"id": survey_id, **clean}
599	            self.respond(201, result)
600	
601	        def route(self):
602	            location = urlsplit(self.path).path
603	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
604	
605	            if location == "/api/surveys":
606	                allowed = ["GET", "POST"]
607	            elif location in ("/", "/health"):
608	                allowed = ["GET"]
609	            elif detail_match:
610	                allowed = ["GET"]
611	            else:
612	                self.respond(404, {"error": "not found"})
613	                return
614	
615	            if self.command not in allowed:
616	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
617	                return
618	
619	            if location == "/":
620	                self.respond(200, PAGE, html=True)
621	            elif location == "/health":
622	                self.respond(200, {"status": "ok", "product": PRODUCT})
623	            elif location == "/api/surveys":
624	                if self.command == "POST":
625	                    self.create_survey()
626	                else:
627	                    self.list_surveys()
628	            else:
629	                detail = survey_detail(int(detail_match.group(1)))
630	                if detail is None:
631	                    self.respond(404, {"error": "not found"})
632	                else:
633	                    self.respond(200, detail)
634	
635	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
636	
637	    def stop(_signal, _frame):
638	        raise KeyboardInterrupt
639	
640	    signal.signal(signal.SIGTERM, stop)
641	    server = None
642	    try:
643	        server = HTTPServer((args.host, args.port), Handler)
644	        host, port = server.server_address[:2]
645	        address = f"[{host}]" if ":" in host else host
646	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
647	        server.serve_forever()
648	    except KeyboardInterrupt:
649	        pass
650	    finally:
651	        if server is not None:
