        h("p", {class: "field-err opt-err"}),
        h("button", {type: "button", class: "link add-opt"}, "添加选项")
      );
      card.querySelector(".add-opt").addEventListener("click", () => {
        options.append(optionRow());
        renumber();
        options.querySelector(".opt-row:last-child .opt-text").focus();
      });
