      }
      const q = {
        type: card.dataset.type,
        title: qTitle,
        required: card.querySelector(".q-required").checked
      };
      if (card.dataset.type === "single_choice") {
        const optInputs = [...card.querySelectorAll(".opt-text")];
        const values = optInputs.map(el => el.value.trim());
