// Minimal CDP driver for end-to-end UI checks.
const BASE = "http://127.0.0.1:18080";

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function newPage() {
  const list = await (await fetch("http://127.0.0.1:19222/json/new?about:blank", {method: "PUT"})).json();
  const ws = new WebSocket(list.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  };
  function send(method, params = {}) {
    const myId = ++id;
    return new Promise(resolve => {
      pending.set(myId, resolve);
      ws.send(JSON.stringify({id: myId, method, params}));
    });
  }
  await send("Page.enable");
  await send("Runtime.enable");
  return {
    async navigate(hash) {
      const res = await send("Page.navigate", {url: BASE + "/#" + hash});
      await sleep(300);
      return res;
    },
    async eval(expr) {
      const r = await send("Runtime.evaluate", {expression: expr, returnByValue: true, awaitPromise: true});
      if (r.result.exceptionDetails) throw new Error("JS error: " + JSON.stringify(r.result.exceptionDetails.exception && r.result.exceptionDetails.exception.description));
      return r.result.result && r.result.result.value;
    },
    close() { ws.close(); }
  };
}

const results = [];
function check(name, cond, extra) {
  results.push({name, ok: !!cond, extra});
  console.log(`${cond ? "PASS" : "FAIL"} - ${name}${extra !== undefined ? " :: " + JSON.stringify(extra) : ""}`);
}

const page = await newPage();
try {
  // 1. Home page: list shows current titles
  await page.navigate("/");
  let titles = await page.eval(`[...document.querySelectorAll('#survey-list a')].map(a=>a.textContent)`);
  check("home lists surveys", titles.length === 3, titles);

  // 2. Detail page has 编辑草稿 entry
  await page.navigate("/surveys/2");
  let detailTitle = await page.eval(`document.querySelector('h2').textContent`);
  check("detail shows updated title", detailTitle.includes("修改后的标题"), detailTitle);
  let editHref = await page.eval(`document.querySelector('a.btn[href$="/edit"]')?.getAttribute('href')`);
  check("detail has edit link", editHref === "#/surveys/2/edit", editHref);

  // 3. Enter edit: all saved content prefilled in order
  await page.navigate("/surveys/2/edit");
  let formHeading = await page.eval(`document.querySelector('form h2').textContent`);
  check("edit heading", formHeading.includes("编辑问卷草稿 #2"), formHeading);
  let state = await page.eval(`({
    title: document.querySelector('#survey-title').value,
    desc: document.querySelector('#survey-desc').value,
    qs: [...document.querySelectorAll('.q-card')].map(c => ({
      type: c.dataset.type,
      num: c.querySelector('.q-index').textContent,
      title: c.querySelector('.q-title').value,
      required: c.querySelector('.q-required').checked,
      opts: [...c.querySelectorAll('.opt-text')].map(o=>o.value)
    }))
  })`);
  check("prefilled title", state.title === "修改后的标题", state.title);
  check("prefilled desc empty", state.desc === "", JSON.stringify(state.desc));
  check("prefilled 2 questions order/type/required", state.qs.length === 2 &&
    state.qs[0].type === "single_choice" && state.qs[0].required === false &&
    state.qs[1].type === "single_choice" && state.qs[1].title === "新增单选题", state.qs);
  check("prefilled option order", JSON.stringify(state.qs[0].opts) === JSON.stringify(["丙","甲","丁"]), state.qs[0].opts);

  // 4. Edit: change title/desc, delete 1st question, modify/add/delete option on 2nd,
  //    then required checkbox; numbers must update.
  await page.eval(`
    document.querySelector('#survey-title').value = "浏览器里改的标题";
    document.querySelector('#survey-desc').value = "新说明\\n第二行\\"引号\\"";
    const cards = document.querySelectorAll('.q-card');
    // delete first question (原单选(改))
    cards[0].querySelector('.q-head .link.danger').click();
  `);
  let afterDelete = await page.eval(`[...document.querySelectorAll('.q-card .q-index')].map(e=>e.textContent)`);
  check("renumber after question delete", JSON.stringify(afterDelete) === JSON.stringify(["第 1 题"]), afterDelete);

  await page.eval(`
    const card = document.querySelector('.q-card');
    // set required, change first option text
    card.querySelector('.q-required').click();
    const opts = card.querySelectorAll('.opt-row');
    opts[0].querySelector('.opt-text').value = "改了的x";
    // delete second option (y), then add a new one
    opts[1].querySelector('.link.danger').click();
    card.querySelector('.add-opt').click();
    card.querySelector('.opt-row:last-child .opt-text').value = "新选项z";
  `);
  let optState = await page.eval(`[...document.querySelectorAll('.opt-index')].map(e=>e.textContent)`);
  check("option renumber after delete/add", JSON.stringify(optState) === JSON.stringify(["选项 1","选项 2"]), optState);

  // 5. Save via PUT, should navigate to detail showing new content
  await page.eval(`document.querySelector('#draft-form button[type=submit]').click()`);
  await sleep(600);
  let hash = await page.eval(`location.hash`);
  check("returns to detail after save", hash === "#/surveys/2", hash);
  let saved = await (await fetch(BASE + "/api/surveys/2")).json();
  check("server stored edited content",
    saved.title === "浏览器里改的标题" &&
    saved.description === '新说明\n第二行"引号"' &&
    saved.questions.length === 1 &&
    saved.questions[0].title === "新增单选题" &&
    saved.questions[0].required === true &&
    JSON.stringify(saved.questions[0].options) === JSON.stringify(["改了的x","新选项z"]),
    saved);
  let detailShows = await page.eval(`document.querySelector('h2').textContent + ' | ' + document.querySelector('.detail-desc')?.textContent`);
  check("detail page shows saved content", detailShows.includes("浏览器里改的标题") && detailShows.includes('第二行"引号"'), detailShows);

  // home list sees new title
  await page.navigate("/");
  titles = await page.eval(`[...document.querySelectorAll('#survey-list a')].map(a=>a.textContent)`);
  check("home list updated title", titles.some(t => t.includes("浏览器里改的标题")) && titles.length === 3, titles);

  // 6. Cancel discards edits
  await page.navigate("/surveys/2/edit");
  await page.eval(`
    document.querySelector('#survey-title').value = "取消后不应存在";
    document.querySelector('.q-card .q-head .link.danger').click(); // delete the only question
    document.querySelector('.add-opt'); // noop ref
  `);
  // now click 取消 (the anchor added in edit mode)
  await page.eval(`document.querySelector('#draft-form a.btn.secondary').click()`);
  await sleep(300);
  hash = await page.eval(`location.hash`);
  check("cancel returns to detail", hash === "#/surveys/2", hash);
  // re-enter edit: last successfully saved content, question back
  await page.navigate("/surveys/2/edit");
  let reenter = await page.eval(`({t: document.querySelector('#survey-title').value, n: document.querySelectorAll('.q-card').length, opts: document.querySelectorAll('.opt-text').length})`);
  check("re-edit shows last saved content", reenter.t === "浏览器里改的标题" && reenter.n === 1 && reenter.opts === 2, reenter);

  // 7. Validation failure keeps inputs, shows error, stays on edit page
  await page.eval(`
    document.querySelector('#survey-title').value = "   ";
    document.querySelector('#draft-form button[type=submit]').click();
  `);
  await sleep(300);
  let failed = await page.eval(`({
    hash: location.hash,
    bannerShown: !document.querySelector('#form-banner').hidden,
    bannerText: document.querySelector('#form-banner').textContent,
    qStillThere: document.querySelectorAll('.q-card').length,
    descKept: document.querySelector('#survey-desc').value
  })`);
