    // set required, change first option text
    card.querySelector('.q-required').click();
    const opts = card.querySelectorAll('.opt-row');
    opts[0].querySelector('.opt-text').value = "改了的x";
    // delete second option (y), then add a new one
    opts[1].querySelector('.link.danger').click();
    card.querySelector('.add-opt').click();
    card.querySelector('.opt-row:last-child .opt-text').value = "新选项z";
  `);
